import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 综合复习与自测 · 第55–63课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第二册：实践与进步 · 综合复习与自测 · 第55–63课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-2/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第46–54课","link":"/life/english/new-concept/book-2/review-part-06"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第64–72课","link":"/life/english/new-concept/book-2/review-part-08"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第46–54课","link":"/life/english/new-concept/book-2/review-part-06"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第64–72课","link":"/life/english/new-concept/book-2/review-part-08"}},"headers":[],"relativePath":"life/english/new-concept/book-2/review-part-07.md","filePath":"life/english/new-concept/book-2/review-part-07.md"}'),n={name:"life/english/new-concept/book-2/review-part-07.md"};function l(r,e,i,h,p,d){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-综合复习与自测-·-第55–63课" tabindex="-1">第二册：实践与进步 · 综合复习与自测 · 第55–63课 <a class="header-anchor" href="#第二册-实践与进步-·-综合复习与自测-·-第55–63课" aria-label="Permalink to &quot;第二册：实践与进步 · 综合复习与自测 · 第55–63课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-55-·-一般过去时与事件顺序" tabindex="-1">Lesson 55 · 一般过去时与事件顺序 <a class="header-anchor" href="#lesson-55-·-一般过去时与事件顺序" aria-label="Permalink to &quot;Lesson 55 · 一般过去时与事件顺序 {#lesson-55-·-一般过去时与事件顺序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> People once believed that the field contained gold.</p><h3 id="练习-1-54" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-54" aria-label="Permalink to &quot;练习 1 {#练习-1-54}&quot;">​</a></h3><p>填 dig 的过去式：They ___ three holes.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> dug</p><p><strong>解析：</strong> dig 的过去式和过去分词均为 dug。</p></details><p><strong>表达迁移：</strong> 写一个预期落空但产生另一种价值的故事，区分原先信念与发现。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>People once believed that the field contained gold. A survey found only old pottery. The village opened a small historical display instead.</p><p>第一句的组织方式：believed 是主句过去式，that 从句 contained 是当时的信念内容，不代表作者认可它为事实。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：gold 是不可数物质名词，通常不写 a gold；a piece of gold 才表示一块。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-055">回看本课</a></p><h2 id="lesson-56-·-比较级与比较范围" tabindex="-1">Lesson 56 · 比较级与比较范围 <a class="header-anchor" href="#lesson-56-·-比较级与比较范围" aria-label="Permalink to &quot;Lesson 56 · 比较级与比较范围 {#lesson-56-·-比较级与比较范围}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The new car was much faster than the team&#39;s previous model.</p><h3 id="练习-1-55" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-55" aria-label="Permalink to &quot;练习 1 {#练习-1-55}&quot;">​</a></h3><p>选 very/much：The car was ___ faster.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> much 可以修饰比较级，very 通常不直接修饰比较级。</p></details><p><strong>表达迁移：</strong> 比较两款车辆或设备，给出速度优势及一个代价，不编造真实品牌数据。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The new car was much faster than the team&#39;s previous model. However, its tyres wore out sooner. The engineers chose reliability for the next race.</p><p>第一句的组织方式：much 修饰比较级 faster，than 后明确比较对象；previous model 与 new car 都指车型。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：more faster 重复比较标记；用 faster 或 much faster。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-056">回看本课</a></p><h2 id="lesson-57-·-情态动词的意义与形式" tabindex="-1">Lesson 57 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-57-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 57 · 情态动词的意义与形式 {#lesson-57-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Would you like to see a different size?</p><h3 id="练习-1-56" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-56" aria-label="Permalink to &quot;练习 1 {#练习-1-56}&quot;">​</a></h3><p>填 to/for：Would you like ___ try it on?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> would like 后接 to 不定式。</p></details><p><strong>表达迁移：</strong> 写三句服务对话：提供帮助、确认尺寸、回应库存情况。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Would you like to see a different size? The customer asked for a smaller coat. The assistant checked the stock without commenting on her clothes.</p><p>第一句的组织方式：Would you like 后接 to see，a different size 是宾语；would 在此不表过去时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Would you like seeing 通常不是提出这次邀请的用法；用 Would you like to see。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-057">回看本课</a></p><h2 id="lesson-58-·-时间、原因与让步从句" tabindex="-1">Lesson 58 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-58-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 58 · 时间、原因与让步从句 {#lesson-58-·-时间、原因与让步从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Although the flood damaged the garden, it led to better drainage.</p><h3 id="练习-1-57" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-57" aria-label="Permalink to &quot;练习 1 {#练习-1-57}&quot;">​</a></h3><p>补全：The damage led ___ a new drainage plan.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> lead to 为固定搭配。</p></details><p><strong>表达迁移：</strong> 写一个损失后得到改善的例子，避免把损失本身说成完全有益。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Although the flood damaged the garden, it led to better drainage. Residents replaced the blocked pipes. The next heavy shower caused no flooding.</p><p>第一句的组织方式：Although 从句承认不利事实，主句 led to 引出后续结果；it 指 flood。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Although ..., but ... 在标准英语中不作这种成对连接；保留一个连接词。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-058">回看本课</a></p><h2 id="lesson-59-·-动词、宾语与补足语" tabindex="-1">Lesson 59 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-59-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 59 · 动词、宾语与补足语 {#lesson-59-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The new flap lets the cat enter without waking us.</p><h3 id="练习-1-58" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-58" aria-label="Permalink to &quot;练习 1 {#练习-1-58}&quot;">​</a></h3><p>选 enter/to enter：The flap lets the cat ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> enter</p><p><strong>解析：</strong> let 的主动使役结构接不带 to 的原形。</p></details><p><strong>表达迁移：</strong> 写三句帮助宠物适应新物件的过程，包含 let 和 without doing。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The new flap lets the cat enter without waking us. At first, the cat was afraid of it. A week later, it used the flap confidently.</p><p>第一句的组织方式：lets 为单数谓语，the cat 是宾语，enter 是原形补足语；without waking 为介词加动名词。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：lets the cat to enter 多了 to；allows the cat enter 则少了 to。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-059">回看本课</a></p><h2 id="lesson-60-·-将来表达与安排" tabindex="-1">Lesson 60 · 将来表达与安排 <a class="header-anchor" href="#lesson-60-·-将来表达与安排" aria-label="Permalink to &quot;Lesson 60 · 将来表达与安排 {#lesson-60-·-将来表达与安排}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The guide predicted that we would see clear skies by evening.</p><h3 id="练习-1-59" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-59" aria-label="Permalink to &quot;练习 1 {#练习-1-59}&quot;">​</a></h3><p>填 will/would：He predicted that the rain ___ stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> would</p><p><strong>解析：</strong> 主句从过去视角转述未来，常用 would。</p></details><p><strong>表达迁移：</strong> 写一次天气预测与实际结果，明确谁预测、如何准备、最后怎样。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The guide predicted that we would see clear skies by evening. We kept our raincoats anyway. The clouds finally broke just before sunset.</p><p>第一句的组织方式：predicted 为过去报告动词，would see 是从过去视角看将来，by evening 给出截止时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：predict 不等于 promise；前者是判断未来，后者是作出承担义务的承诺。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-060">回看本课</a></p><h2 id="lesson-61-·-被动语态与信息重点" tabindex="-1">Lesson 61 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-61-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 61 · 被动语态与信息重点 {#lesson-61-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By Friday, the replacement camera will have been tested twice.</p><h3 id="练习-1-60" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-60" aria-label="Permalink to &quot;练习 1 {#练习-1-60}&quot;">​</a></h3><p>补全被动：The camera will have ___ tested twice.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 将来完成时被动结构为 will have been done。</p></details><p><strong>表达迁移：</strong> 写一份设备检查计划，区分测试截止、结果评审与批准条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>By Friday, the replacement camera will have been tested twice. Engineers will compare the results on Saturday. They will approve the launch only if both tests pass.</p><p>第一句的组织方式：will have been tested 为将来完成时被动，By Friday 给出截止点，twice 是次数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will have tested 若主语是 camera 会变成摄像机执行测试；此处需 been 表被动。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-061">回看本课</a></p><h2 id="lesson-62-·-完成进行时与持续活动" tabindex="-1">Lesson 62 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-62-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 62 · 完成进行时与持续活动 {#lesson-62-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The volunteers had been planting seeds for hours when the rain began.</p><h3 id="练习-1-61" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-61" aria-label="Permalink to &quot;练习 1 {#练习-1-61}&quot;">​</a></h3><p>填 plant：They had been ___ seeds for hours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> planting</p><p><strong>解析：</strong> 过去完成进行时为 had been doing。</p></details><p><strong>表达迁移：</strong> 描述一次持续劳动被天气打断的经历，补充一个较晚的观察结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The volunteers had been planting seeds for hours when the rain began. They stopped to protect the tools. A month later, small green shoots appeared.</p><p>第一句的组织方式：had been planting 强调雨开始前持续的活动，when rain began 提供过去参照点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had been planted 是被动或状态相关结构，不表示志愿者持续播种；用 planting。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-062">回看本课</a></p><h2 id="lesson-63-·-间接引语与视角转换" tabindex="-1">Lesson 63 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-63-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 63 · 间接引语与视角转换 {#lesson-63-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The host asked me not to repeat the joke.</p><h3 id="练习-1-62" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-62" aria-label="Permalink to &quot;练习 1 {#练习-1-62}&quot;">​</a></h3><p>填否定位置：The host asked me ___ repeat it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> not to</p><p><strong>解析：</strong> 否定不定式通常为 not to do。</p></details><p><strong>表达迁移：</strong> 写一次说话不合场合后的调整，转述一个否定请求。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The host asked me not to repeat the joke. I had mistaken the occasion for an informal party. I apologised and moved to the main topic.</p><p>第一句的组织方式：asked 后接 me，再用 not to repeat 转述否定请求；the joke 是 repeat 的宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：asked me to not repeat 有时可见，但常规教学优先 not to repeat；did not ask 与 asked not 不同。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-063">回看本课</a></p>',76)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
